import manifest from '../data/images.json'

/**
 * Every photo in public/images/, as generated by scripts/images/process_images.py:
 * { src, alt, width, height } per image, grouped by use. Credits: public/images/CREDITS.md.
 */
export const IMAGES = {
  hero: manifest.hero ?? [],
  genres: manifest.genres ?? {},
  instruments: manifest.instruments ?? {},
  covers: manifest.covers ?? [],
  scenes: manifest.scenes ?? {},
  emptyStates: manifest.emptyStates ?? {},
}

const hash = (text) => {
  let h = 2166136261
  for (const ch of String(text)) h = Math.imul(h ^ ch.charCodeAt(0), 16777619)
  return h >>> 0
}

/** A stable cover photo for an item (competition, challenge, exercise...), picked by seed. */
export const coverFor = (seed) => {
  const covers = IMAGES.covers
  return covers.length ? covers[hash(seed) % covers.length] : null
}

/** The photo for an instrument name like "PIANO" (falls back to a cover). */
export const instrumentImage = (instrument) =>
  IMAGES.instruments[String(instrument || '').toLowerCase()] ?? coverFor(instrument)

/** The photo for a genre / performance category like "HIP_HOP" (falls back to a cover). */
const GENRE_ALIASES = { randb: 'rnb', hip: 'hiphop' }
export const genreImage = (genre) => {
  const key = String(genre || '').toLowerCase().replace(/[^a-z]/g, '')
  return IMAGES.genres[GENRE_ALIASES[key] ?? key] ?? coverFor(genre)
}
